import{_ as n,C as l,c as r,o as s,ag as i,j as e,G as o}from"./chunks/framework.Bw-5EFTY.js";const w=JSON.parse('{"title":"Managing Affiliates","description":"","frontmatter":{},"headers":[],"relativePath":"guide/admin-portal/managing-affiliates.md","filePath":"guide/admin-portal/managing-affiliates.md","lastUpdated":1752483014000}'),f={name:"guide/admin-portal/managing-affiliates.md"};function g(d,a,h,u,p,m){const t=l("ZoomableImage");return s(),r("div",null,[a[0]||(a[0]=i('<h1 id="managing-affiliates" tabindex="-1">Managing Affiliates <a class="header-anchor" href="#managing-affiliates" aria-label="Permalink to &quot;Managing Affiliates&quot;">​</a></h1><p>In FluentAffiliate, managing your affiliates is easy and organized. The Affiliates page is your central hub to see a complete overview of all your affiliates, check their performance, manage their status, and even add new affiliates manually.</p><p>In this guide, we&#39;ll walk you through what you can do on the Affiliates page.</p><h2 id="affiliates-dashboard-overview" tabindex="-1">Affiliates Dashboard Overview <a class="header-anchor" href="#affiliates-dashboard-overview" aria-label="Permalink to &quot;Affiliates Dashboard Overview&quot;">​</a></h2><p>First, go to the <strong>Affiliates</strong> tab from the FluentAffiliate menu. There, you&#39;ll see the affiliate dashboard with all your site&#39;s affiliate details.</p><p>Here&#39;s what you&#39;ll find in the <strong>Affiliates</strong> section:</p><h3 id="adding-a-new-affiliate" tabindex="-1">Adding a New Affiliate <a class="header-anchor" href="#adding-a-new-affiliate" aria-label="Permalink to &quot;Adding a New Affiliate&quot;">​</a></h3><p>At the top right corner, you&#39;ll find the <strong>+ New Affiliate</strong> button. Click this to manually add a new affiliate to your program without requiring them to sign up themselves. (We&#39;ll show you how to do that later in this guide.) If you want affiliates to register themselves, see <a href="./../affiliate-portal/how-to-register-as-an-affiliate">How to Register as an Affiliate</a>.</p><h3 id="filtering-your-affiliates" tabindex="-1">Filtering Your Affiliates <a class="header-anchor" href="#filtering-your-affiliates" aria-label="Permalink to &quot;Filtering Your Affiliates&quot;">​</a></h3><p>Just below the page title, you&#39;ll see filter tabs that let you quickly segment your list:</p><ul><li><strong>All:</strong> Shows every affiliate in your program.</li><li><strong>Active:</strong> Shows only approved and active affiliates.</li><li><strong>Pending:</strong> Shows affiliates who have registered but are awaiting your approval.</li><li><strong>Inactive:</strong> Shows affiliates who have been deactivated.</li></ul><h3 id="affiliates-details-table" tabindex="-1">Affiliates Details Table <a class="header-anchor" href="#affiliates-details-table" aria-label="Permalink to &quot;Affiliates Details Table&quot;">​</a></h3><p>This is the heart of the page, where every affiliate is listed with their key performance details. This gives you a clear and immediate picture of how each partner is doing. The columns include:</p><ul><li><strong>Affiliate:</strong> The name and email address of the affiliate.</li><li><strong>Rate:</strong> Their specific commission rate.</li><li><strong>Total Earnings:</strong> The total commissions they have ever earned.</li><li><strong>Unpaid Earnings:</strong> The approved earnings that are waiting to be paid out.</li><li><strong>Referrals:</strong> The total number of successful referrals they&#39;ve made.</li><li><strong>Visits:</strong> The total number of clicks their links have received.</li><li><strong>Registered at:</strong> The date they joined your affiliate program.</li><li><strong>Status:</strong> Their current account status (e.g., Active, Pending, Inactive).</li></ul>',14)),e("p",null,[o(t,{src:"/guide/public/images/admin-portal/managing-affiliates/affiliate-list-overview.webp",alt:"Affiliate Management Dashboard"})]),a[1]||(a[1]=i('<h3 id="managing-individual-affiliates" tabindex="-1">Managing Individual Affiliates <a class="header-anchor" href="#managing-individual-affiliates" aria-label="Permalink to &quot;Managing Individual Affiliates&quot;">​</a></h3><p>At the end of each affiliate&#39;s row, you&#39;ll see a three-dot menu. Clicking this opens a list of actions you can take for that specific affiliate:</p><ul><li><strong>Edit:</strong> Opens a panel where you can update the affiliate&#39;s details, such as their status or commission rate.</li><li><strong>Delete:</strong> Permanently removes the affiliate from your program.</li></ul><h3 id="search-and-sort-tools" tabindex="-1">Search and Sort Tools <a class="header-anchor" href="#search-and-sort-tools" aria-label="Permalink to &quot;Search and Sort Tools&quot;">​</a></h3><p>To the top-right of the table, you&#39;ll find icons to help you organize your view:</p><ul><li><strong>Search Bar:</strong> Quickly locate affiliates by typing their name or email address.</li><li><strong>Column Selector:</strong> Customize your table view using the <strong>Columns</strong> button. Check or uncheck columns based on what info you want to display.</li><li><strong>Sort Options:</strong> Sort affiliates by <strong>ID</strong>, <strong>Total Earnings</strong>, <strong>Unpaid Earnings</strong>, <strong>Referrals</strong>, <strong>Visits</strong>, or <strong>Registration Date</strong>. You can also choose between ascending or descending order, then click <strong>Apply</strong> to update.</li></ul>',6)),e("p",null,[o(t,{src:"/guide/public/images/admin-portal/managing-affiliates/search-and-sort-tools.webp",alt:"Affiliate Search and Sort Tools"})]),a[2]||(a[2]=i('<h3 id="pagination-buttons" tabindex="-1">Pagination Buttons <a class="header-anchor" href="#pagination-buttons" aria-label="Permalink to &quot;Pagination Buttons&quot;">​</a></h3><p>If you have a large number of affiliates, the controls at the bottom of the page help you navigate your list easily. You can set the number of <strong>affiliates to show per page</strong> and use the <strong>arrow</strong> buttons to move between pages.</p><h3 id="add-a-new-affiliate" tabindex="-1">Add a New Affiliate <a class="header-anchor" href="#add-a-new-affiliate" aria-label="Permalink to &quot;Add a New Affiliate&quot;">​</a></h3><p>Want to manually add an affiliate to your site? Here&#39;s how:</p><p>Click the <strong>New Affiliate</strong> button. A form will slide in from the right side of your screen.</p>',5)),e("p",null,[o(t,{src:"/guide/public/images/admin-portal/managing-affiliates/add-new-affiliate-button.webp",alt:"Add New Affiliate Button"})]),a[3]||(a[3]=i("<p>Fill in the following fields:</p><ul><li><strong>Select User</strong> – Select the user you want to turn into an affiliate.</li><li><strong>Rate Type</strong> – Choose how they&#39;ll earn (fixed or percentage).</li><li><strong>Status</strong> – Set the affiliate status (approved, pending, or rejected).</li><li><strong>Payment Email</strong> – Enter their PayPal or preferred payment email.</li><li><strong>Note</strong> – (Optional) Add any notes for internal use.</li></ul><p>Hit the <strong>Create Affiliate</strong> button to create a new affiliate.</p>",3)),e("p",null,[o(t,{src:"/guide/public/images/admin-portal/managing-affiliates/add-affiliate-form.webp",alt:"Add Affiliate Form"})]),a[4]||(a[4]=e("p",null,"That's it! Your new affiliate will now appear in the list.",-1))])}const b=n(f,[["render",g]]);export{w as __pageData,b as default};
